// Auto-generated pre-seeded database snapshot for zero-config serverless deployments
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';

export const EMBEDDED_DB_GZIP_BASE64 = '';

export function restoreEmbeddedDatabase(targetPath: string): boolean {
  try {
    const dir = path.dirname(targetPath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    const compressed = Buffer.from(EMBEDDED_DB_GZIP_BASE64, 'base64');
    const decompressed = zlib.gunzipSync(compressed);
    fs.writeFileSync(targetPath, decompressed);
    return true;
  } catch (err) {
    console.error('Failed to restore embedded database snapshot:', err);
    return false;
  }
}
